// Constitution des lots d'avis à lire.
//
// LA CONSIGNE EST REPRISE MOT POUR MOT du script qu'elle remplace : le profil
// métier gouverne 74 exclusions sur 77, sa sensibilité a été mesurée (§ 11.8),
// et le porter en workflow ne doit RIEN changer à ce qu'il dit. Toute retouche
// invaliderait la mesure de sensibilité déjà publiée.
const runId = $('Ouvrir le run').first().json.run_id;
const TAILLE_LOT = 8;   // au-delà, le modèle raccourcit ses justifications
const CONSIGNE = "Tu conseilles une PME suisse de MÉCANIQUE DE PRÉCISION (canton de Neuchâtel,
environ 50 personnes). Son métier : l'usinage de pièces métalliques à tolérances serrées —
tournage, fraisage, décolletage, rectification — en petites et moyennes séries, en
SOUS-TRAITANCE pour des donneurs d'ordre des secteurs horloger, médical (implants,
instruments), automobile et aérospatial.

Ce qu'elle SAIT faire : produire des pièces sur plan, des composants mécaniques, des
sous-ensembles usinés, de l'outillage, des prototypes et des séries.

Ce qu'elle NE FAIT PAS, et qu'il ne faut jamais lui proposer : vendre des appareils
complets (drones, hélicoptères, véhicules, machines finies), des consommables, des
logiciels, des prestations de service (maintenance, nettoyage, transport, conseil,
formation), du mobilier, des matières premières brutes, ou des équipements qu'elle
revendrait sans les produire.

Pour CHAQUE avis de marché public de la liste, réponds à une seule question :
cet appel est-il exécutable par cet atelier, et que faut-il faire maintenant ?

Trois axes :

1. adressable (0-2)
   0 = hors du savoir-faire. Appareil complet, service, consommable, logiciel,
       matière brute, mobilier. C'est le cas le plus fréquent : n'hésite pas à
       mettre 0, une liste courte et juste vaut mieux qu'une liste longue.
   1 = périphérique. Des pièces sont impliquées mais l'objet principal est
       ailleurs, ou le lot devrait être décomposé pour être atteignable.
   2 = coeur de métier. L'avis porte sur des pièces usinées, des composants
       mécaniques, des sous-ensembles, de l'outillage ou des prototypes.

2. piece_concernee — ce qu'il faudrait produire, en quelques mots concrets et
   tirés de l'avis. Si rien n'est à produire, laisse vide.

3. action_proposee — le GESTE, pas un conseil général. Formule-le à l'impératif
   et rends-le exécutable : qui contacter, pour demander quoi. Exemple utile :
   « Demander le cahier des charges à l'acheteur pour vérifier les tolérances et
   les matières. » Exemple inutile, à ne jamais produire : « Étudier
   l'opportunité. » Si adressable vaut 0, laisse vide.

N'INVENTE RIEN. Ne suppose ni matière, ni tolérance, ni volume qui ne soit dans
l'intitulé. Si l'intitulé est trop vague pour trancher, mets adressable 1 et dis-le
dans la justification.

Réponds UNIQUEMENT par un JSON strict, sans texte autour :
{"lectures": [{"publication_number": "", "adressable": 0, "piece_concernee": "",
"action_proposee": "", "justification": ""}]}";

// Les lignes sont relues à la source : le nœud d'ouverture du run, placé
// entre les deux, ne les transmet pas.
const avis = $('Lire les appels sans lecture').all().map(x => x.json).filter(a => a.publication_number);
if (!avis.length) // RIEN À TRAITER N'EST PAS UNE ERREUR : c'est le cas nominal d'un dispositif
  // rejoué à intervalle régulier. Lever une exception ici interromprait le
  // workflow AVANT la clôture — le run resterait ouvert, et la vue de santé des
  // exécutions compterait indéfiniment une exécution en cours qui ne l'est plus.
  // Constaté au rejeu de bout en bout du 25.08.2026 (run 138).
  // On rend un item marqueur, que les nœuds suivants laissent passer sans écrire.
  return [{ json: { _rien_a_faire: true, run_id: runId } }];

const lots = [];
for (let i = 0; i < avis.length; i += TAILLE_LOT) {
  const lot = avis.slice(i, i + TAILLE_LOT);
  const contenu = CONSIGNE + '

Avis :
' + lot.map(a =>
    '- ' + a.publication_number + ' [' + (a.sector_code || 'hors grille') + ', '
    + (a.acheteur_pays || '?') + ', CPV ' + (a.cpv_texte || '?') + ', '
    + a.jours_restants + ' jours restants] : ' + String(a.titre || '').slice(0, 260)
  ).join('
');
  lots.push({ json: {
    run_id: runId, numeros: lot.map(a => a.publication_number),
    corps: { contents: [{ parts: [{ text: contenu }] }],
             generationConfig: { temperature: 0, responseMimeType: 'application/json' } }
  }});
}
return lots;

// Normalisation des lectures, et contrôle AVANT écriture.
//
// Deux garde-fous repris du script : on n'écrit que les numéros RÉELLEMENT
// soumis dans le lot — un modèle peut inventer une référence — et on n'accepte
// que les trois valeurs d'adressabilité du barème. Ce qui sort du cadre est
// consigné en incident, jamais écrit.
const sorties = [], incidents = [];
// Le marqueur posé en amont quand il n'y a rien à traiter traverse sans écrire.
if ($input.all().some(x => x.json && x.json._rien_a_faire)) {
  return [{ json: { _rien_a_faire: true, _incidents: [] } }];
}
const lignes = $input.all();
for (let i = 0; i < lignes.length; i++) {
  const r = lignes[i].json;
  const t = $('Préparer les lots').itemMatching(i).json;
  if (r.error) { incidents.push('lot ' + (i+1) + ' : appel en échec (' + JSON.stringify(r.error).slice(0,160) + ')'); continue; }
  // Le modèle rend parfois des blocs de raisonnement avant le texte : on
  // concatène TOUS les blocs de type texte, jamais seulement le premier.
  const parts = (r && r.candidates && r.candidates[0] && r.candidates[0].content && r.candidates[0].content.parts) || [];
  const brut = parts.filter(p => p.text).map(p => p.text).join('\n').trim();
  if (!brut) { incidents.push('lot ' + (i+1) + ' : réponse sans texte'); continue; }
  const m = /```(?:json)?\s*(\{[\s\S]*\})\s*```/.exec(brut);
  let rep;
  try { rep = JSON.parse(m ? m[1] : brut); }
  catch (e) { incidents.push('lot ' + (i+1) + ' : JSON non parsable'); continue; }
  // Normalisation en chaîne des deux côtés : la comparaison d'un identifiant
  // rendu par Postgres et d'un identifiant rendu par le modèle ne doit pas
  // dépendre de leur type de sérialisation.
  const admis = new Set(t.numeros.map(String));
  for (const l of (rep.lectures || [])) {
    if (!admis.has(String(l.publication_number))) { incidents.push('numéro hors lot ignoré : ' + l.publication_number); continue; }
    if ([0,1,2].indexOf(l.adressable) === -1) { incidents.push('adressable hors barème pour ' + l.publication_number); continue; }
    sorties.push({ json: {
      publication_number: l.publication_number,
      modele: $env.MODELE_GOOGLE || 'gemini-3.7-flash',
      profil: 'A_metier_declare',
      adressable: l.adressable,
      piece_concernee: (l.piece_concernee || '').slice(0,300) || null,
      action_proposee: (l.action_proposee || '').slice(0,400) || null,
      justification: (l.justification || '').slice(0,400),
      _incidents: incidents
    }});
  }
}
if (!sorties.length) throw new Error('aucune lecture exploitable — incidents : ' + (incidents.join(' | ') || 'aucun'));
return sorties;
